// Generates a template's typed API from its provider's published description.
//
//   pnpm --filter @platform/template-generator generate <template> [source-file]
//
// The template's scripts/operations.ts names the source and decides how each
// operation is offered. Without a source file, the generator downloads the
// current description. It writes the generated files and the shared runtime
// files into the template; review the diff before committing.
import { execFileSync } from "node:child_process";
import { copyFileSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { z } from "zod";
import { generateGraphql } from "./graphql.ts";

const [template, sourcePath] = process.argv.slice(2);

if (!template || !/^[a-z0-9-]+$/.test(template))
  throw new Error("Usage: generate <template> [source-file]");

const here = dirname(fileURLToPath(import.meta.url));

const directory = join(here, "../../../templates", template);

const service = z.object({
  name: z.string(),
  className: z.string(),
  result: z.string(),
  properties: z.string(),
});

const configuration = z.object({
  generator: z.discriminatedUnion("kind", [
    z.object({ kind: z.literal("graphql"), source: z.url(), service }),
  ]),
  mutations: z.record(
    z.string(),
    z.union([z.enum(["create", "update", "delete"]), z.object({ hidden: z.string() })]),
  ),
  queries: z.record(
    z.string(),
    z.union([z.object({ hidden: z.string() }), z.object({ name: z.string() })]),
  ),
});

const rules = configuration.parse(
  await import(pathToFileURL(join(directory, "scripts/operations.ts")).href),
);

const { generator } = rules;

const source = sourcePath
  ? readFileSync(sourcePath, "utf8")
  : await (async () => {
      const response = await fetch(generator.source);

      if (!response.ok) throw new Error(`${generator.source} answered HTTP ${response.status}`);

      return response.text();
    })();

const header = `// Generated by the Widefleet template generator from ${generator.service.name}'s
// published API description and scripts/operations.ts. Do not edit; regenerate
// from the Widefleet repository:
//   pnpm --filter @platform/template-generator generate ${template}
`;

const generated = generateGraphql(source, rules, generator.service, header);

const written = Object.entries(generated.files).map(([path, text]) => {
  writeFileSync(join(directory, path), text);

  return join(directory, path);
});

// Runtime files every generated template shares, kept once in this package.
for (const file of ["selection.ts", "approval.ts"])
  copyFileSync(join(here, "runtime", file), join(directory, "src", file));

// Formatted as the repository formats its sources, so regenerating changes only what changed.
execFileSync(join(here, "../../../node_modules/.bin/oxfmt"), written, { stdio: "inherit" });

console.log(generated.summary);
